#include"operation.h"


void setup() {
  Serial.begin(115200);
  Serial.println("Enter two numbers separated by a comma (e.g., 25,15):");
}

void loop() {
  if (Serial.available() > 0) {
// Read the first integer (stops reading at the comma)
    int num1 = Serial.parseInt();

// Read the second integer (stops reading at the newline or buffer end)
    int num2 = Serial.parseInt();

// Clear trailing characters (like \r or \n) from the buffer
    while (Serial.available() > 0) {
      Serial.read();
    }

    int sum = add(num1,num2);
// Before (ESP32 only)
// Serial.printf("%d + %d = %d \n", num1, num2, sum);

// After (all boards)
    Serial.print(num1);
    Serial.print(" + ");
    Serial.print(num2);
    Serial.print(" = ");
    Serial.println(sum);

// Display the result
// Serial.printf("%d + %d = %d \n", num1, num2, sum);

    int subs = sub(num1,num2);

// Display the result
// Serial.printf("%d - %d = %d \n", num1, num2, sub);
// Before (ESP32 only)
// Serial.printf("%d + %d = %d \n", num1, num2, sum);

// After (all boards)
    Serial.print(num1);
    Serial.print(" - ");
    Serial.print(num2);
    Serial.print(" = ");
    Serial.println(subs);


    int multi = mul(num1,num2);
    Serial.print(num1);
    Serial.print(" * ");
    Serial.print(num2);
    Serial.print(" = ");
    Serial.println(multi);

    int divi = div(num1,num2);
    Serial.print(num1);
    Serial.print(" / ");
    Serial.print(num2);
    Serial.print(" = ");
    Serial.println(divi);

float fdivi = f_div(num1,num2);
    Serial.print(num1);
    Serial.print(" / ");
    Serial.print(num2);
    Serial.print(" = ");
    Serial.println(fdivi);

int modu = mod(num1,num2);
    Serial.print(num1);
    Serial.print(" * ");
    Serial.print(num2);
    Serial.print(" = ");
    Serial.println(modu);
  }
}

